package zw.chibaro;
import java.util.*;import java.math.BigDecimal;import java.time.*;import java.net.*;import java.net.http.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=${TEST_DATABASE_URL:jdbc:postgresql://localhost:55433/chibaro_test}","spring.session.redis.namespace=chibaro:test:sessions","app.bootstrap-email=","app.bootstrap-password=","PUBLISHING_ENABLED=false"})
class PlatformTest {
 @Autowired JdbcTemplate db;@Autowired Operations ops;@Autowired MarketingService marketing;@Autowired TransactionTemplate tx;@Value("${local.server.port}") int port;
 Contracts.Request request(UUID key,int weight){return new Contracts.Request(key,"Integration Test","+263770000001","","Beitbridge A","Beitbridge B","furniture-transport","Sofa and table",BigDecimal.valueOf(weight),LocalDate.now().plusDays(3),LocalTime.of(10,0),"DISCUSS","Test only",true,"");}
 void rollback(Runnable work){tx.executeWithoutResult(s->{try{work.run();}finally{s.setRollbackOnly();}});}
 @Test void migrationSeedHasOnlyVerifiedBusinessFacts(){assertEquals(5,db.queryForObject("select count(*) from business_services",Integer.class));assertEquals(3000,db.queryForObject("select capacity_kg from vehicles limit 1",Integer.class));}
 @Test void duplicateSubmissionCreatesOneQuoteLeadAndNotification(){rollback(()->{UUID key=UUID.randomUUID();var first=ops.submit(request(key,3100),false);var second=ops.submit(request(key,3100),false);assertEquals(first.get("reference"),second.get("reference"));assertEquals(true,first.get("review_required"));assertEquals(1,db.queryForObject("select count(*) from quotation_requests where submission_key=?",Integer.class,key));assertEquals(1,db.queryForObject("select count(*) from leads l join quotation_requests q on q.id=l.quote_id where q.submission_key=?",Integer.class,key));assertEquals(1,db.queryForObject("select count(*) from notification_outbox n join quotation_requests q on q.id=n.resource_id where q.submission_key=?",Integer.class,key));});}
 @Test void bookingsStartUnconfirmedAndPreventOverload(){rollback(()->{UUID key=UUID.randomUUID();var result=ops.submit(request(key,3100),true);assertEquals("REQUESTED",result.get("status"));UUID id=db.queryForObject("select id from bookings where submission_key=?",UUID.class,key);ops.booking(id,new Contracts.BookingUpdate("PENDING_CONFIRMATION",null,null),"test");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ops.booking(id,new Contracts.BookingUpdate("CONFIRMED",UUID.fromString("00000000-0000-0000-0000-000000000001"),null),"test"));});}
 @Test void quoteNeedsPriceAndAcceptanceBeforeConversion(){rollback(()->{UUID key=UUID.randomUUID();ops.submit(request(key,500),false);UUID id=db.queryForObject("select id from quotation_requests where submission_key=?",UUID.class,key);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ops.convert(id,"test"));ops.quote(id,new Contracts.QuoteUpdate("UNDER_REVIEW",null,null,null),"test");assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ops.quote(id,new Contracts.QuoteUpdate("QUOTED",null,null,null),"test"));});}
 @Test void acceptedQuoteConversionIsIdempotent(){rollback(()->{UUID key=UUID.randomUUID();ops.submit(request(key,500),false);UUID id=db.queryForObject("select id from quotation_requests where submission_key=?",UUID.class,key);ops.quote(id,new Contracts.QuoteUpdate("UNDER_REVIEW",null,null,null),"test");ops.quote(id,new Contracts.QuoteUpdate("QUOTED",BigDecimal.TEN,"USD","Test condition"),"test");ops.quote(id,new Contracts.QuoteUpdate("ACCEPTED",BigDecimal.TEN,"USD","Test condition"),"test");assertEquals(ops.convert(id,"test"),ops.convert(id,"test"));});}
 @Test void invalidBookingTransitionRejected(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->Operations.transition("REQUESTED","COMPLETED",Operations.BOOKINGS));}
 @Test void adminRequiresLoginAndPublicWritesRequireCsrf() throws Exception {var client=HttpClient.newHttpClient();assertEquals(401,client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/admin/quotes")).GET().build(),HttpResponse.BodyHandlers.ofString()).statusCode());assertEquals(403,client.send(HttpRequest.newBuilder(URI.create("http://localhost:"+port+"/api/v1/quotes")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{}" )).build(),HttpResponse.BodyHandlers.ofString()).statusCode());}
 @Test void editedApprovedContentLosesApproval(){rollback(()->{var draft=new MarketingService.Draft("Moving in Beitbridge?","Contact TransChibaro Logistics to discuss your load.","#Beitbridge","FACEBOOK",null);UUID id=(UUID)marketing.save(draft,null,"test").get("id");marketing.approve(id,"test");assertEquals("APPROVED",db.queryForObject("select status from marketing_posts where id=?",String.class,id));marketing.save(draft,id,"test");assertEquals("DRAFT",db.queryForObject("select status from marketing_posts where id=?",String.class,id));assertNull(db.queryForObject("select approved_by from marketing_posts where id=?",String.class,id));});}
 @Test void unverifiedClaimsAreRejected(){assertThrows(org.springframework.web.server.ResponseStatusException.class,()->MarketingService.policy("Guaranteed same-day transport to Botswana"));}
 @Test void tokenEncryptionAuthenticatesAccountAndUsesRandomNonce(){String key=Base64.getEncoder().encodeToString(new byte[32]);var vault=new TokenVault(key);String one=vault.encrypt("a","test-token"),two=vault.encrypt("a","test-token");assertNotEquals(one,two);assertFalse(one.contains("test-token"));assertEquals("test-token",vault.decrypt("a",one));assertThrows(IllegalStateException.class,()->vault.decrypt("b",one));}
 @Test void workerDoesNotPublishJobTwice(){rollback(()->{UUID campaign=UUID.randomUUID(),post=UUID.randomUUID(),account=UUID.randomUUID(),job=UUID.randomUUID();db.update("insert into marketing_campaigns(id,name,instructions,approved) values (?,'Test','Test',true)",campaign);db.update("insert into marketing_posts(id,campaign_id,platform,heading,caption,status,approved_by,approved_at) values (?,?,'FACEBOOK','Test','Transport enquiries','SCHEDULED','test',now())",post,campaign);db.update("insert into social_accounts(id,provider,display_name,external_id,token_ciphertext,token_expires_at,permissions,status) values (?,'FACEBOOK','Mock',?,'ENCRYPTED-TEST',now()+interval '1 day','test','CONNECTED')",account,account.toString());db.update("insert into publishing_jobs(id,post_id,account_id,status,run_at) values (?,?,?,'PENDING',now())",job,post,account);var calls=new java.util.concurrent.atomic.AtomicInteger();PublishingAdapter mock=new PublishingAdapter(){public String provider(){return "FACEBOOK";}public boolean eligible(Map<String,Object> p,Map<String,Object> a){return true;}public Result publish(Map<String,Object> p,Map<String,Object> a,String key){calls.incrementAndGet();return new Result(Outcome.SUCCESS,"mock-post-1",null,null);}};var worker=new PublishingWorker(db,tx,List.of(mock),false);worker.runOne();worker.runOne();assertEquals(1,calls.get());assertEquals("SUCCEEDED",db.queryForObject("select status from publishing_jobs where id=?",String.class,job));assertEquals("mock-post-1",db.queryForObject("select platform_post_id from marketing_posts where id=?",String.class,post));});}
}
